static __inline void projectile_clamp_channel_reference_ifelse(float &value)
{
    if (value < 0.0f) {
        value = 0.0f;
    } else if (value > 1.0f) {
        value = 1.0f;
    }
}

extern "C" void projectile_update(void)

static __inline void projectile_clamp_channel_reference_return(float &value)
{
    if (value < 0.0f) {
        value = 0.0f;
        return;
    }
    if (value > 1.0f) {
        value = 1.0f;
    }
}

extern "C" void projectile_update(void)

static __inline void projectile_clamp_channel_pointer_ifelse(float *value)
{
    if (*value < 0.0f) {
        *value = 0.0f;
    } else if (*value > 1.0f) {
        *value = 1.0f;
    }
}

extern "C" void projectile_update(void)

static __inline void projectile_clamp_channel_reference_independent(float &value)
{
    if (value < 0.0f) {
        value = 0.0f;
    }
    if (value > 1.0f) {
        value = 1.0f;
    }
}

